// The Zeta mark + wordmark for both reels, from brandArt.js (generated by
// scripts/brand/brand.py). Replaces the old portal-frame LOGO everywhere.
//
// The mark builds the way the strip is folded: top bar left → right, the
// diagonal top-right → bottom-left, the bottom bar left → right, then the
// contact shadows land. Each face grows along its own direction by an affine
// stretch, so edges stay crisp at every frame. Amber is NOT in the mark — it
// is the signal point that flares at the impact and fades, the reel's one glow.
const LOGO = (id) => {
  const g = BRAND.grad, sh = BRAND.shadow, f = BRAND.faces
  const lin = (k, v, stops) => { const [x1, y1, x2, y2] = v.split(' '); return `<linearGradient id="${id}${k}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}">${stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join('')}</linearGradient>` }
  const shd = (k, s) => `<linearGradient id="${id}${k}" gradientUnits="userSpaceOnUse" x1="${s.x[0]}" y1="${s.x[1]}" x2="${s.x[2]}" y2="${s.x[3]}"><stop offset="0" stop-color="${s.color}" stop-opacity="${s.alpha}"/><stop offset="1" stop-color="${s.color}" stop-opacity="0"/></linearGradient>`
  return `<svg id="${id}" viewBox="0 0 64 64" width="64" height="64" overflow="visible"><defs>${Object.entries(g).map(([k, v]) => lin(k, v.v, v.stops)).join('')}${Object.entries(sh).map(([k, s]) => shd(k, s)).join('')}</defs>
  <polygon class="lg-top" points="${f.top}" fill="url(#${id}t)"/><polygon class="lg-sh1" points="${f.shTop}" fill="url(#${id}s1)"/>
  <polygon class="lg-diag" points="${f.diag}" fill="url(#${id}d)"/><polygon class="lg-sh2" points="${f.shBot}" fill="url(#${id}s2)"/>
  <polygon class="lg-bot" points="${f.bot}" fill="url(#${id}b)"/>
  <circle class="lg-pt" cx="33" cy="32" r="3.2" fill="#f2b53a" opacity="0"/></svg>`
}
// stretch by s along unit vector (ux, uy), holding (ax, ay) fixed
function stretch(el, s, ux, uy, ax, ay) {
  const k = s - 1, a = 1 + k * ux * ux, b = k * ux * uy, d = 1 + k * uy * uy
  el.setAttribute('transform', `matrix(${a} ${b} ${b} ${d} ${ax - (a * ax + b * ay)} ${ay - (b * ax + d * ay)})`)
  el.style.opacity = s > 0.001 ? 1 : 0
}
const R2 = Math.SQRT1_2
/** p = { top, diag, bot, shade } each 0‥1 (a spring may overshoot a little). */
function markBuild(svg, p) {
  stretch($('.lg-top', svg), p.top, 1, 0, 6, 15)
  stretch($('.lg-diag', svg), p.diag, -R2, R2, 55, 10)
  stretch($('.lg-bot', svg), p.bot, 1, 0, 4, 49)
  const sh = clamp(p.shade ?? 1, 0, 1)
  op($('.lg-sh1', svg), sh * clamp(p.diag, 0, 1)); op($('.lg-sh2', svg), sh * clamp(p.bot, 0, 1))
}
/** The diagonal grows out from its centre (for builds that start at a point). */
function markFromCentre(svg, p) {
  stretch($('.lg-diag', svg), p.diag, -R2, R2, 33, 32)
  stretch($('.lg-top', svg), p.top, -1, 0, 62, 15)
  stretch($('.lg-bot', svg), p.bot, 1, 0, 4, 49)
  const sh = clamp(p.shade ?? 1, 0, 1)
  op($('.lg-sh1', svg), sh * clamp(p.top, 0, 1)); op($('.lg-sh2', svg), sh * clamp(p.bot, 0, 1))
}
/** The amber signal point on the fold centre: k = 0 hidden, 1 full flare. */
function markFlash(svg, k, glow = 1) {
  const pt = $('.lg-pt', svg)
  pt.setAttribute('opacity', clamp(k, 0, 1))
  pt.setAttribute('r', 3.2 * (0.4 + 0.9 * clamp(k, 0, 1.6)))
  pt.style.filter = k > 0.01 ? `drop-shadow(0 0 ${2 + 5 * glow * k}px rgba(242,181,58,.95))` : ''
}
/** The ZETA wordmark as four outline letters, cap height `capH` px, in `color`.
 *  Returns { el, letters, set(rise[], tracking) }: rise 0 = below the clip, 1 = home;
 *  tracking in em (0.04 is the logo's own). */
function WORD(capH, color = '#f2f5f9') {
  const W0 = BRAND.word.w, H0 = BRAND.word.h, EM = BRAND.word.em
  const k = capH / H0
  const el = h('div', { class: 'abs', style: { width: W0 * k * 1.6 + 'px', height: capH + 'px', overflow: 'hidden' } })
  const sv = h('svg', { viewBox: `0 0 ${W0 * 1.6} ${H0}`, width: W0 * k * 1.6, height: capH, fill: color, style: { display: 'block', overflow: 'visible' } }, el)
  const letters = BRAND.word.letters.map((L) => h('path', { d: L.d }, sv))
  const set = (rise, tracking = 0.04) => letters.forEach((p, i) => {
    const dx = BRAND.word.letters[i].x + i * (tracking - 0.04) * EM
    p.setAttribute('transform', `translate(${dx} ${(1 - clamp(rise[i] ?? 1, 0, 1.2)) * H0 * 1.15})`)
  })
  set([1, 1, 1, 1])
  return { el, letters, set, width: (tr = 0.04) => (W0 + 3 * (tr - 0.04) * EM) * k }
}
/** Static inline wordmark (for cards/covers), cap height capH px. */
const WORD_SVG = (capH, color) => {
  const k = capH / BRAND.word.h
  return `<svg viewBox="0 0 ${BRAND.word.w} ${BRAND.word.h}" width="${BRAND.word.w * k}" height="${capH}" fill="${color}" style="display:block">${BRAND.word.letters.map((L) => `<path transform="translate(${L.x} 0)" d="${L.d}"/>`).join('')}</svg>`
}
